-- Check: the sample SIT records.
SELECT display_id, title, status, (SELECT count(*) FROM jsonb_object_keys(field_values)) AS fields_filled
FROM public.local_register_records
WHERE register_id = '00000000-0000-4000-9001-000000000017'::uuid AND id::text LIKE '00000000-0000-4000-b017-%'
ORDER BY id;
